arduino.setup:
Serial.begin(9600);
pinMode(${TRIG}, OUTPUT);
pinMode(${ECHO}, INPUT);
Serial.println("HC-SR04 Ready");

arduino.loop:
digitalWrite(${TRIG}, LOW);
delayMicroseconds(2);
digitalWrite(${TRIG}, HIGH);
delayMicroseconds(10);
digitalWrite(${TRIG}, LOW);
long dur_${COMP_SUFFIX} = pulseIn(${ECHO}, HIGH);
float cm_${COMP_SUFFIX} = dur_${COMP_SUFFIX} / 58.2;
float inch_${COMP_SUFFIX} = dur_${COMP_SUFFIX} / 148.0;
Serial.print("Distance: ");
Serial.print(cm_${COMP_SUFFIX}, 1);
Serial.print(" cm | ");
Serial.print(inch_${COMP_SUFFIX}, 1);
Serial.println(" in");
delay(500);
